fn rolling_max(s: &Vec<i8>) -> Option<i8> {
    if s.len() < 2 {
        return None;
    }

    // We want to find the largest and second largest distinct values.
    // Initialize to the smallest possible i8 so any element will replace them.
    let mut max = i8::MIN;
    let mut second_max = i8::MIN;

    for &val in s.iter() {
        if val > max {
            // New max found, shift previous max to second max
            second_max = max;
            max = val;
        } else if val > second_max && val < max {
            // val is distinct and between max and second_max
            second_max = val;
        }
    }

    // If second_max was never updated distinct from max, it means either:
    // - all elements are equal (max == second_max because we initialized second_max to MIN)
    // - or there is only one unique element
    // If second_max == i8::MIN and second_max == max, it means all are equal
    // For arrays with at least two elements, if all are equal, second largest = max (same value).
    if second_max == i8::MIN {
        // Check if all elements are equal to max:
        // if yes, return max
        // otherwise, no second largest exists, return None
        let all_equal = s.iter().all(|&x| x == max);
        if all_equal {
            Some(max)
        } else {
            None
        }
    } else {
        Some(second_max)
    }
}